(() => {
  'use strict';
  const KEY = 'bort-journal-v1';
  const CATS = {fuel:'Топливо',service:'Сервис',wash:'Мойка',other:'Другое',income:'Доход'};
  const ICONS = {fuel:'↗',service:'⌁',wash:'◌',other:'·'};
  const $ = (s, root=document) => root.querySelector(s);
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const id = () => crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  const isoDate = d => { const x=new Date(d); return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`; };
  const today = isoDate(new Date());
  const dateLabel = v => {if(!v)return '—';const d=new Date(`${v}T12:00:00`);return Number.isNaN(+d)?v:d.toLocaleDateString('ru-RU',{day:'numeric',month:'short',year:'numeric'}).replace(' г.','')};
  const money = v => new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(+v||0);
  const num = v => {if(v===null||v===undefined||String(v).trim()==='')return null;const n=Number(String(v).trim().replace(/\s/g,'').replace(',','.'));return Number.isFinite(n)?n:null};
  const makeDemo = () => {
    const base = new Date(); const ago = n => {const d=new Date(base);d.setDate(d.getDate()-n);return isoDate(d)};
    const data=[
      {date:ago(2),category:'fuel',title:'Заправка · Shell',amount:5820,litres:48.5,pricePerLitre:120,fullTank:true,odometer:42860,notes:'АИ-95',guid:'demo-f1'},
      {date:ago(8),category:'wash',title:'Комплексная мойка',amount:1450,odometer:42690,guid:'demo-w1'},
      {date:ago(17),category:'fuel',title:'Заправка · Лукойл',amount:4930,litres:41.2,pricePerLitre:119.66,fullTank:true,odometer:42411,guid:'demo-f2'},
      {date:ago(27),category:'service',title:'Замена масла',amount:12700,odometer:42082,notes:'ТО · масло и фильтры',guid:'demo-s1'},
      {date:ago(36),category:'fuel',title:'Заправка · Shell',amount:5340,litres:44.7,pricePerLitre:119.46,fullTank:true,odometer:41700,guid:'demo-f3'},
      {date:ago(51),category:'other',title:'Парковка',amount:650,odometer:41315,guid:'demo-o1'},
      {date:ago(62),category:'fuel',title:'Заправка · Лукойл',amount:4620,litres:39.1,pricePerLitre:118.16,fullTank:true,odometer:41004,guid:'demo-f4'},
      {date:ago(76),category:'wash',title:'Мойка кузова',amount:950,odometer:40652,guid:'demo-w2'},
      {date:ago(90),category:'fuel',title:'Заправка · Shell',amount:5110,litres:43.6,pricePerLitre:117.2,fullTank:true,odometer:40311,guid:'demo-f5'},
      {date:ago(105),category:'service',title:'Шиномонтаж',amount:4900,odometer:39920,guid:'demo-s2'}
    ];
    return {version:1,records:data.map(x=>({id:id(),...x})),demo:true,vehicle:{make:'Volvo',model:'V60',year:'2021',fuel:'Бензин',plate:'А 482 МР 799'}};
  };
  let loadProblem=false;
  function safeLoad(){try{const raw=localStorage.getItem(KEY);if(!raw)return makeDemo();const x=JSON.parse(raw);if(x?.version===1&&Array.isArray(x.records)&&x.vehicle)return x;throw new Error('Unexpected journal format')}catch(e){loadProblem=true;console.warn('Could not load local journal',e);return {version:1,records:[],vehicle:{},demo:false}}}
  let state=safeLoad(), view='dashboard', filter='all', query='', dateFrom='',dateTo='', editId=null, importPreview=null;
  function save(replaceUnreadable=false){if(loadProblem&&!replaceUnreadable){toast('Сохранение повреждено или недоступно. Журнал не изменён.',true);return false}try{localStorage.setItem(KEY,JSON.stringify(state));if(replaceUnreadable)loadProblem=false;return true}catch(e){toast('Не удалось сохранить данные на устройстве',true);return false}}
  function toast(message,error=false){document.querySelector('.notice')?.remove();const n=document.createElement('div');n.className=`notice${error?' error':''}`;n.textContent=message;document.body.append(n);setTimeout(()=>n.remove(),3000)}
  const ordered = () => [...state.records].sort((a,b)=>(b.date||'').localeCompare(a.date||'') || String(b.time||'').localeCompare(String(a.time||'')) || (b.odometer||0)-(a.odometer||0));
  const sum = arr => arr.reduce((s,r)=>s+(+r.amount||0),0);
  function filtered(){return ordered().filter(r=>(filter==='all'||r.category===filter)&&(!query||`${r.title} ${r.notes} ${CATS[r.category]}`.toLowerCase().includes(query.toLowerCase()))&&(!dateFrom||r.date>=dateFrom)&&(!dateTo||r.date<=dateTo))}
  function lastOdo(){return state.records.filter(r=>Number.isFinite(+r.odometer)&&+r.odometer>0).sort((a,b)=>(b.date||'').localeCompare(a.date||''))[0]?.odometer??null}
  function header(){ $('#todayLabel').textContent=new Date().toLocaleDateString('ru-RU',{weekday:'short',day:'numeric',month:'short'});$('#crumbTitle').textContent=({dashboard:'Обзор',history:'История',settings:'Данные и настройки'})[view];document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const v=state.vehicle||{},title=document.querySelector('.vehicle-title b'),sub=document.querySelector('.vehicle-sub'),plate=document.querySelector('.plate');if(title)title.textContent=vehicleText();if(sub)sub.textContent=[v.year,v.fuel].filter(Boolean).join(' · ');if(plate)plate.textContent=v.plate||''; }
  function vehicleText(){const v=state.vehicle||{};return [v.make,v.model].filter(Boolean).join(' ')||'Автомобиль'}
  function categoriesTotal(arr){return Object.keys(CATS).map(k=>[k,sum(arr.filter(r=>r.category===k))]).filter(x=>x[1]>0)}
  function svgChart(arr){
    const expenses=arr.filter(r=>r.category!=='income'&&r.date).sort((a,b)=>a.date.localeCompare(b.date));
    if(!expenses.length)return `<div class="empty"><strong>Пока нет событий</strong>Добавьте запись — здесь появится динамика расходов.</div>`;
    const months=[];for(let i=5;i>=0;i--){const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-i);months.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`)}
    const vals=months.map(m=>sum(expenses.filter(r=>r.date.startsWith(m))));const max=Math.max(...vals,1),w=600,h=160,left=42,right=12,top=12,bottom=25,pw=w-left-right,ph=h-top-bottom;
    const pts=vals.map((v,i)=>[left+i*pw/(vals.length-1),top+ph-(v/max)*(ph*.88)]);const line=pts.map((p,i)=>`${i?'L':'M'}${p[0]},${p[1]}`).join(' '),area=`${line} L${pts.at(-1)[0]},${top+ph} L${pts[0][0]},${top+ph} Z`;
    const grid=[0,.5,1].map(q=>{const y=top+ph-q*ph;return `<line class="gridline" x1="${left}" y1="${y}" x2="${w-right}" y2="${y}"/><text class="axis-label" x="0" y="${y+3}">${money(max*q)}</text>`}).join('');
    const labels=months.map((m,i)=>`<text class="axis-label" text-anchor="middle" x="${pts[i][0]}" y="${h-4}">${new Date(`${m}-01T12:00:00`).toLocaleDateString('ru-RU',{month:'short'})}</text>`).join('');
    const events=expenses.filter(r=>r.category==='fuel'||r.category==='service').slice(-12).map(r=>{const m=months.indexOf(r.date.slice(0,7));if(m<0)return'';const p=pts[m];return `<g class="chart-event" tabindex="0" role="button" aria-label="${esc(r.title)}, ${money(r.amount)} ₽" data-record="${esc(r.id)}"><line x1="${p[0]}" y1="${p[1]+7}" x2="${p[0]}" y2="${top+ph}"/><circle cx="${p[0]}" cy="${p[1]}" r="4"/></g>`}).join('');
    return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Расходы по месяцам">${grid}<path class="chart-area" d="${area}"/><path class="chart-line" d="${line}"/>${events}${pts.map(p=>`<circle class="chart-point" cx="${p[0]}" cy="${p[1]}" r="2.5"/>`).join('')}${labels}</svg>`;
  }
  function donut(arr){const cats=categoriesTotal(arr),total=sum(arr);let offset=0;const colors={fuel:'#9fc85e',service:'#4b5c44',wash:'#d8a178',other:'#d9ddd4'};const rings=cats.map(([k,v])=>{const pct=100*v/(total||1),dash=pct;const out=`<circle cx="50" cy="50" r="39" stroke="${colors[k]}" stroke-dasharray="${dash} ${100-dash}" stroke-dashoffset="${-offset}" pathLength="100"/>`;offset+=pct;return out}).join('');return `<div class="donut"><svg viewBox="0 0 100 100"><circle class="donut-bg" cx="50" cy="50" r="39"/>${rings}</svg><div class="donut-center"><strong>${money(total)} ₽</strong><small>за всё время</small></div></div>`}
  function eventRow(r){return `<div class="event-row" data-record="${esc(r.id)}"><span class="event-icon ${esc(r.category)}">${ICONS[r.category]||'·'}</span><span><span class="event-name">${esc(r.title||CATS[r.category]||'Расход')}</span><span class="event-meta">${dateLabel(r.date)}${r.demo?'<span class="demo-tag">демо</span>':''}</span></span><span class="event-odo">${r.odometer?`${money(r.odometer)} км`:'—'}</span><span class="event-price">${money(r.amount)} ₽</span></div>`}
  function renderDashboard(){const all=state.records.filter(r=>r.category!=='income'), fuel=state.records.filter(r=>r.category==='fuel'), odo=lastOdo(), total=sum(all), monthsAgo=new Date();monthsAgo.setDate(1);monthsAgo.setMonth(monthsAgo.getMonth()-1);const currentMonth=isoDate(new Date()).slice(0,7),monthCost=sum(all.filter(r=>r.date?.startsWith(currentMonth)));const lastFuel=fuel.filter(r=>r.litres&&r.fullTank&&r.odometer).sort((a,b)=>a.date.localeCompare(b.date));const intervals=Core.fuelIntervals(fuel);const newest=intervals.at(-1);let economy=newest?newest.litresPer100Km.toLocaleString('ru-RU',{maximumFractionDigits:1}):'—'
    const parts=categoriesTotal(all),latest=ordered().slice(0,4),veh=state.vehicle||{};
    return `<div class="page-heading"><div><div class="eyebrow">СРЕДА, КОТОРАЯ ЗНАЕТ СВОЙ ПРОБЕГ</div><h1>Ваш автомобиль,<br class="mobile-break"> в деталях.</h1><p>Расходы и события ${esc(vehicleText())} — собраны в одном месте.</p></div><button class="btn btn-primary" data-action="add"><span class="plus">＋</span>Добавить запись</button></div>
    ${state.demo?'<div class="demo-banner"><i class="demo-dot"></i><span><strong>Демонстрационные данные</strong> · Это вымышленные записи. При импорте они заменятся вашей историей.</span></div>':''}
    <section class="stats"><article class="stat-card"><div class="stat-label">Расходы за месяц <em>↗</em></div><div class="stat-value">${money(monthCost)} <span class="stat-unit">₽</span></div><div class="stat-meta">${new Date().toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</div></article><article class="stat-card"><div class="stat-label">Всего за всё время <em>◷</em></div><div class="stat-value">${money(total)} <span class="stat-unit">₽</span></div><div class="stat-meta">${all.length} ${plural(all.length,'запись','записи','записей')}</div></article><article class="stat-card"><div class="stat-label">Последний пробег <em>↗</em></div><div class="stat-value">${odo?money(odo):'—'} <span class="stat-unit">км</span></div><div class="stat-meta">${odo?'По последней записи с пробегом':'Пробег ещё не записан'}</div></article><article class="stat-card"><div class="stat-label">Расход за интервал <em>⌁</em></div><div class="stat-value">${economy} <span class="stat-unit">л / 100 км</span></div><div class="stat-meta">${newest?`Между ${dateLabel(newest.from)} и ${dateLabel(newest.to)} · ${newest.costPerKm.toLocaleString('ru-RU',{maximumFractionDigits:2})} ₽/км по топливу`:'Нужны полные заправки, известные пробег и объём'}</div></article></section>
    <div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">Расходы автомобиля</div><div class="panel-sub">Сумма записей по месяцам</div></div><span class="period">6 месяцев</span></div><div class="chart-wrap">${svgChart(all)}</div><div class="panel-foot"><span class="legend"><span><i></i>Расходы</span><span><i class="expense"></i>События</span></span><span>По данным журнала</span></div></section>
    <section class="panel breakdown"><div class="panel-head"><div><div class="panel-title">Структура расходов</div><div class="panel-sub">Категории за всё время</div></div></div><div class="donut-row">${donut(all)}<div class="legend-list">${parts.length?parts.map(([k,v])=>`<div class="legend-item"><i></i><span>${CATS[k]||'Другое'}</span><b>${Math.round(v/(total||1)*100)}%</b></div>`).join(''):'<span class="panel-sub">Пока нет данных</span>'}</div></div><div class="category-detail">Суммируются только расходы, добавленные или импортированные в журнал.</div></section></div>
    <section class="panel activity"><div class="panel-head"><div><div class="panel-title">Последние события</div><div class="panel-sub">Заправки, обслуживание и другие записи</div></div><button class="text-link" data-view="history">Вся история&nbsp; →</button></div><div class="event-list">${latest.length?latest.map(eventRow).join(''):'<div class="empty"><strong>Журнал пока пуст</strong>Добавьте первую запись или импортируйте историю.</div>'}</div></section>`}
  function renderHistory(){const rows=filtered();return `<div class="page-heading"><div><div class="eyebrow">ЖУРНАЛ СОБЫТИЙ</div><h1>История автомобиля</h1><p>Все расходы и события, которые вы внесли в журнал.</p></div><button class="btn btn-primary" data-action="add"><span class="plus">＋</span>Добавить</button></div>${state.demo?'<div class="demo-banner"><i class="demo-dot"></i><span><strong>Демонстрационные данные</strong> · При импорте они заменятся вашей историей.</span></div>':''}<div class="section-toolbar" style="margin-bottom:13px"><div class="history-controls"><input class="input-control" id="searchRecords" placeholder="Поиск по названию или заметке" value="${esc(query)}"><input class="input-control" id="fromDate" type="date" aria-label="Дата с" value="${esc(dateFrom)}"><input class="input-control" id="toDate" type="date" aria-label="Дата по" value="${esc(dateTo)}"></div><select class="select-control" id="categoryFilter"><option value="all">Все категории</option>${Object.entries(CATS).map(([k,v])=>`<option value="${k}" ${filter===k?'selected':''}>${v}</option>`).join('')}</select><span class="panel-sub">${rows.length} ${plural(rows.length,'запись','записи','записей')} · ${money(sum(rows))} ₽</span></div><section class="panel history-list"><div class="history-head"><span>Событие</span><span>Дата</span><span>Пробег</span><span>Сумма</span><span></span></div>${rows.length?rows.map(r=>`<div class="history-item" data-record="${esc(r.id)}"><div class="history-what"><span class="event-icon ${esc(r.category)}">${ICONS[r.category]||'·'}</span><strong>${esc(r.title||CATS[r.category]||'Расход')}</strong></div><span class="history-date">${dateLabel(r.date)}${r.demo?' · демо':''}</span><span class="history-odo">${r.odometer?`${money(r.odometer)} км`:'—'}</span><span class="history-cost">${money(r.amount)} ₽</span><button class="row-menu" data-edit="${esc(r.id)}" aria-label="Открыть запись">···</button></div>`).join(''):'<div class="empty"><strong>Записей не найдено</strong>Измените фильтры или добавьте событие.</div>'}</section>`}
  function renderSettings(){const v=state.vehicle||{};return `<div class="page-heading"><div><div class="eyebrow">ВАШ ЖУРНАЛ</div><h1>Данные и настройки</h1><p>Управляйте записями и данными автомобиля.</p></div></div><div class="settings-grid"><section class="panel settings-card"><h2>Импорт истории</h2><p>Загрузите экспорт Fuelio в CSV. Мы покажем найденные записи перед добавлением. Поддерживаются разделы Vehicle, Log, Costs и CostCategories.</p><div class="setting-actions"><button class="btn btn-primary" data-action="import">Выбрать CSV</button><button class="btn btn-secondary" data-action="import-json">Импорт JSON</button></div><p class="import-notes" style="margin-top:12px">Демо-записи будут заменены. Фото и вложения в CSV не входят.</p></section><section class="panel settings-card"><h2>История для покупателя</h2><p>Сохраните локальный HTML-отчёт с историей обслуживания. В отчёт включаются только записи категории «Сервис».</p><div class="setting-actions"><button class="btn btn-secondary" data-action="buyer-report">Скачать историю обслуживания</button></div></section><section class="panel settings-card"><h2>Резервная копия</h2><p>Скачайте копию журнала в формате JSON или перенесите его на другое устройство.</p><div class="setting-actions"><button class="btn btn-secondary" data-action="export">Экспортировать JSON</button><button class="btn btn-secondary" data-action="import-json">Восстановить из JSON</button></div></section><section class="panel settings-card"><h2>Автомобиль</h2><p>${esc(vehicleText())}${v.year?` · ${esc(v.year)}`:''}${v.fuel?` · ${esc(v.fuel)}`:''}${v.plate?` · ${esc(v.plate)}`:''}</p><div class="setting-actions"><button class="btn btn-secondary" data-action="vehicle">Изменить данные</button></div></section><section class="panel settings-card"><h2>Хранение данных</h2><p>Журнал сохраняется в локальном хранилище этого браузера на устройстве. Облачной синхронизации нет.</p><span class="local-lock"><svg viewBox="0 0 16 16"><path d="M4 7V5a4 4 0 0 1 8 0v2m-9 0h10v7H3z"/></svg>Доступ к записям есть только в этом браузере.</span></section></div><div class="storage-note">Расходы и средний расход отражают только записи, которые находятся в журнале. Расчёт л/100 км появляется при наличии двух последовательных полных заправок с известным пробегом.</div>`}
  function plural(n,a,b,c){const n10=n%10,n100=n%100;return n10===1&&n100!==11?a:n10>=2&&n10<=4&&(n100<12||n100>14)?b:c}
  function render(){header();$('#app').innerHTML=view==='dashboard'?renderDashboard():view==='history'?renderHistory():renderSettings()}
  function calcFields(form,changed){if(form.elements.category.value!=='fuel')return;const updates=Core.calculateFuelFields({amount:form.elements.amount.value,litres:form.elements.litres.value,pricePerLitre:form.elements.pricePerLitre.value},changed);for(const [name,value]of Object.entries(updates))form.elements[name].value=value}
  function openRecord(record=null){editId=record?.id||null;const r=record||{};const isFuel=(r.category||'fuel')==='fuel';$('#dialogRoot').innerHTML=`<div class="modal-backdrop" data-close="true"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-header"><div><h2 id="modalTitle">${record?'Изменить запись':'Новое событие'}</h2><p>${!record&&state.demo?'При сохранении демо-примеры будут очищены, чтобы не смешивать их с вашей историей.':'Запись сохранится локально на этом устройстве.'}</p></div><button class="close-modal" data-action="close" aria-label="Закрыть">×</button></div><form id="recordForm"><div class="form-grid"><div class="field"><label for="cat">Категория</label><select name="category" id="cat">${Object.entries(CATS).map(([k,v])=>`<option value="${k}" ${k===(r.category||'fuel')?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="date">Дата</label><input name="date" id="date" type="date" required value="${esc(r.date||today)}"></div><div class="field full"><label for="title">Название</label><input name="title" id="title" maxlength="90" placeholder="Например, заправка на Лукойле" value="${esc(r.title||'')}"></div><div class="field"><label for="amount">Сумма, ₽</label><input name="amount" id="amount" type="number" min="0" step="0.01" value="${esc(r.amount??'')}" placeholder="0"></div><div class="field"><label for="odo">Пробег, км <span class="field-hint">необязательно</span></label><input name="odometer" id="odo" type="number" min="0" step="1" value="${esc(r.odometer??'')}" placeholder="${lastOdo()?`Подсказка: ${money(lastOdo())}`:'Не указан'}"><span class="field-hint">Подсказка не сохраняется автоматически.</span></div><div class="field fuel-field"><label for="litres">Топливо, л</label><input name="litres" id="litres" type="number" min="0" step="0.01" value="${esc(r.litres??'')}" placeholder="0,00"></div><div class="field fuel-field"><label for="priceL">Цена за литр, ₽</label><input name="pricePerLitre" id="priceL" type="number" min="0" step="0.01" value="${esc(r.pricePerLitre??'')}" placeholder="0,00"></div><div class="field full fuel-field"><label class="check-field"><input type="checkbox" name="fullTank" ${r.fullTank?'checked':''}> Полный бак</label><span class="field-hint">Для расчёта расхода нужны две полные заправки и известный пробег.</span></div><div class="field full"><label for="notes">Заметка <span class="field-hint">необязательно</span></label><textarea name="notes" id="notes" maxlength="500" placeholder="Детали, место или комментарий">${esc(r.notes||'')}</textarea></div></div><div class="modal-footer">${record?'<button type="button" class="btn btn-danger" data-action="delete-record">Удалить</button>':'<span></span>'}<div class="footer-actions"><button type="button" class="btn btn-secondary" data-action="close">Отмена</button><button type="submit" class="btn btn-primary">Сохранить запись</button></div></div></form></section></div>`;
    const form=$('#recordForm');const toggle=()=>document.querySelectorAll('.fuel-field').forEach(x=>x.style.display=form.elements.category.value==='fuel'?'grid':'none');toggle();form.elements.category.addEventListener('change',toggle);form.elements.litres.addEventListener('input',()=>calcFields(form,'litres'));form.elements.pricePerLitre.addEventListener('input',()=>calcFields(form,'pricePerLitre'));form.elements.amount.addEventListener('input',()=>calcFields(form,'amount'));form.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(form),category=fd.get('category'),title=String(fd.get('title')||'').trim()||CATS[category]||'Расход',amount=num(fd.get('amount'));if(amount===null||amount<0){toast('Укажите сумму расхода',true);return}if(!Core.normalizeDate(fd.get('date'))){toast('Укажите корректную дату',true);return}const prev=record||{};const item={...prev,id:prev.id||id(),date:fd.get('date'),category,title,amount,odometer:num(fd.get('odometer')),litres:category==='fuel'?num(fd.get('litres')):null,pricePerLitre:category==='fuel'?num(fd.get('pricePerLitre')):null,fullTank:category==='fuel'&&fd.get('fullTank')==='on',notes:String(fd.get('notes')||'').trim(),guid:prev.guid||id()};const oldState=JSON.stringify(state);if(prev.id)state.records=state.records.map(x=>x.id===prev.id?item:x);else{if(state.demo)state.records=[];state.records.push(item)}if(!prev.id)state.demo=false;if(!save()){state=JSON.parse(oldState);return}$('#dialogRoot').innerHTML='';render();toast(prev.id?'Запись обновлена':'Запись добавлена')});}
  function closeDialog(){if(importPreview){importPreview=null}$('#dialogRoot').innerHTML=''}
  function exportJson(){if(loadProblem){toast('Восстановите журнал из проверенной резервной копии перед экспортом.',true);return}const blob=new Blob([JSON.stringify({format:'bort-journal',version:1,exportedAt:new Date().toISOString(),vehicle:state.vehicle,records:state.records},null,2)],{type:'application/json'});download(blob,`bort-journal-${today}.json`);toast('Резервная копия подготовлена')}
  function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
  const Core=window.BortCore;
  const parseCsv=Core.parseCsv;
  const parseFuelio=text=>Core.parseFuelio(text,state.vehicle,id);
  const normalizeDate=Core.normalizeDate;
  function previewImport(result,filename){importPreview=result;const sample=result.records.slice(0,5);$('#dialogRoot').innerHTML=`<div class="modal-backdrop" data-close="true"><section class="modal" role="dialog" aria-modal="true"><div class="modal-header"><div><h2>Проверьте импорт</h2><p>${esc(filename)} · данные пока не сохранены</p></div><button class="close-modal" data-action="close">×</button></div><div class="form-grid"><div class="field full"><div class="preview-summary">Найдено записей: <b>${result.records.length}</b> · заправок ${result.sections.fuel} · расходов ${result.sections.costs}.${result.duplicateCount?` Пропущено дублей: ${result.duplicateCount}.`:''}<br>Автомобиль: <b>${esc([result.vehicle.make,result.vehicle.model,result.vehicle.year].filter(Boolean).join(' ')||'не найден')}</b></div></div><div class="field full"><label>Примеры записей</label><div class="preview-rows">${sample.length?sample.map(r=>`<div class="preview-row"><b>${esc(dateLabel(r.date))} · ${esc(r.title)}</b><span>${money(r.amount)} ₽${r.odometer?` · ${money(r.odometer)} км`:''}</span></div>`).join(''):'<div class="preview-row"><span>Записи не найдены в CSV</span></div>'}</div></div><div class="field full"><div class="import-notes">Автомобильные расходы из раздела Costs классифицируются по названию категории. Пробег 0 сохраняется как неизвестный. Вложения и фотографии из CSV не импортируются. Можно добавить записи к текущим или заменить журнал. При добавлении совпадающие GUID пропускаются; если автомобили различаются, добавление недоступно.</div></div></div><div class="modal-footer"><button class="btn btn-secondary" data-action="close">Отмена</button><div class="footer-actions"><button class="btn btn-secondary" data-action="merge-import" ${sample.length&&!state.demo&&!loadProblem?'':'disabled'}>Добавить к журналу</button><button class="btn btn-primary" data-action="confirm-import" ${sample.length?'':'disabled'}>${state.demo?'Начать с импортированных данных':'Заменить журнал'}</button></div></div></section></div>`}
  async function handleFile(file){if(!file)return;try{const text=await file.text();if(file.name.toLowerCase().endsWith('.json')||file.type==='application/json'){const result=Core.normalizeBackup(JSON.parse(text),id);previewImport(result,file.name)}else{const result=parseFuelio(text);if(!result.records.length)throw new Error('В файле не найдены записи Fuelio');previewImport(result,file.name)}}catch(e){toast(e.message||'Не удалось прочитать файл',true)}}
  function confirmImport(merge=false){if(!importPreview)return;if(loadProblem&&merge){toast('Повреждённый журнал можно восстановить только заменой из проверенной резервной копии.',true);return}const oldState=JSON.stringify(state);const imported=importPreview.records,vehicle=merge?(importPreview.vehicle||state.vehicle):(importPreview.vehicle||{});if(merge&&!state.demo){if(!Core.sameVehicle(state.vehicle,vehicle)){toast('Автомобиль в файле отличается. Используйте замену.',true);return}const keys=new Set(state.records.map(r=>r.guid).filter(Boolean));const additions=[];for(const r of imported){if(r.guid&&keys.has(r.guid))continue;if(r.guid)keys.add(r.guid);additions.push(r)}state.records=[...state.records,...additions];state.vehicle=Object.keys(vehicle).length?vehicle:state.vehicle}else{try{if(!state.demo){const backup=JSON.stringify(state,null,2);localStorage.setItem(KEY+'-backup-'+Date.now(),backup);download(new Blob([backup],{type:'application/json'}),`bort-backup-before-import-${today}.json`)}}catch(e){toast('Не удалось создать резервную копию перед заменой',true);return}state={version:1,records:imported,vehicle,demo:false}}if(!save(loadProblem&&!merge)){state=JSON.parse(oldState);return}importPreview=null;closeDialog();render();toast(merge?'Записи добавлены':'История импортирована')}
  function openVehicle(){const v=state.vehicle||{};$('#dialogRoot').innerHTML=`<div class="modal-backdrop" data-close="true"><section class="modal" role="dialog" aria-modal="true"><div class="modal-header"><div><h2>Данные автомобиля</h2><p>Можно отредактировать после импорта.</p></div><button class="close-modal" data-action="close">×</button></div><form id="vehicleForm"><div class="form-grid"><div class="field"><label>Марка</label><input name="make" value="${esc(v.make||'')}" placeholder="Volvo"></div><div class="field"><label>Модель</label><input name="model" value="${esc(v.model||'')}" placeholder="V60"></div><div class="field"><label>Год</label><input name="year" value="${esc(v.year||'')}" placeholder="2021"></div><div class="field"><label>Тип топлива</label><input name="fuel" value="${esc(v.fuel||'')}" placeholder="Бензин"></div><div class="field full"><label>Госномер</label><input name="plate" value="${esc(v.plate||'')}" placeholder="А 482 МР 799"></div></div><div class="modal-footer"><span></span><div class="footer-actions"><button type="button" class="btn btn-secondary" data-action="close">Отмена</button><button class="btn btn-primary">Сохранить</button></div></div></form></section></div>`;$('#vehicleForm').addEventListener('submit',e=>{e.preventDefault();const previous=JSON.stringify(state);state.vehicle=Object.fromEntries(new FormData(e.currentTarget));if(!save()){state=JSON.parse(previous);return}closeDialog();render();toast('Данные автомобиля обновлены')})}
  document.addEventListener('click',e=>{const viewBtn=e.target.closest('[data-view]');if(viewBtn){view=viewBtn.dataset.view;render();return}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='add'){openRecord();return}if(action==='close'){closeDialog();return}if(action==='import'||action==='import-json'){const file=$('#importFile');file.accept=action==='import'?'.csv,text/csv':'.json,application/json';file.click();return}if(action==='export'){exportJson();return}if(action==='buyer-report'){window.BortReport?.download(state,{serviceOnly:true});return}if(action==='vehicle'){openVehicle();return}if(action==='confirm-import'){confirmImport(false);return}if(action==='merge-import'){confirmImport(true);return}if(action==='delete-record'){if(!editId)return;const oldState=JSON.stringify(state);state.records=state.records.filter(r=>r.id!==editId);if(!save()){state=JSON.parse(oldState);return}closeDialog();render();toast('Запись удалена');return}if(e.target.closest('[data-close="true"]')&&e.target.classList.contains('modal-backdrop')){closeDialog();return}const edit=e.target.closest('[data-edit]');if(edit){const r=state.records.find(x=>x.id===edit.dataset.edit);if(r)openRecord(r);return}const rec=e.target.closest('[data-record]');if(rec){const r=state.records.find(x=>x.id===rec.dataset.record);if(r)openRecord(r)}});
  $('#importFile').addEventListener('change',e=>{handleFile(e.target.files?.[0]);e.target.value=''});
  document.addEventListener('input',e=>{if(['searchRecords','fromDate','toDate'].includes(e.target.id)){if(e.target.id==='searchRecords')query=e.target.value;if(e.target.id==='fromDate')dateFrom=e.target.value;if(e.target.id==='toDate')dateTo=e.target.value;const focused=e.target.id,position=e.target.selectionStart;render();const next=$(`#${focused}`);next?.focus();if(focused==='searchRecords')next?.setSelectionRange(position,position)}});
  document.addEventListener('change',e=>{if(e.target.id==='categoryFilter'){filter=e.target.value;render()}});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#dialogRoot').innerHTML)closeDialog();if((e.key==='Enter'||e.key===' ')&&e.target.matches('.chart-event')){e.preventDefault();const r=state.records.find(x=>x.id===e.target.dataset.record);if(r)openRecord(r)}});
  if('serviceWorker' in navigator && location.protocol.startsWith('http'))window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
  render();
  if(loadProblem)toast('Не удалось прочитать сохранённый журнал. Старые данные оставлены без изменений.',true);
  if(typeof window!=='undefined')window.BortJournal={parseCsv,parseFuelio,normalizeDate};
  if(typeof module!=='undefined'&&module.exports)module.exports={parseCsv,parseFuelio,normalizeDate};
})();
